function detectAndDecode(buffer) {
  const bytes = new Uint8Array(buffer);

  // -- ابحث عن BOM (FF FE) في أول 10 بايتات -----------------------------
  let bomPos = -1;
  for (let i = 0; i < Math.min(10, bytes.length - 1); i++) {
    if (bytes[i] === 0xFF && bytes[i+1] === 0xFE) { bomPos = i; break; }
  }

  if (bomPos >= 0) {
    try {
      const decoder = new TextDecoder("utf-16-le");
      const slice = buffer.slice(bomPos + 2);
      return decoder.decode(slice);
    } catch(e) {
      const start = bomPos + 2;
      const chars = [];
      for (let i = start; i + 1 < bytes.length; i += 2) {
        const c = bytes[i] | (bytes[i+1] << 8);
        if (c !== 0) chars.push(String.fromCharCode(c));
      }
      return chars.join('');
    }
  }

  // -- فحص UTF-16-LE بدون BOM ----------------------------------------------
  let scanStart = 0;
  while (scanStart < 10 && bytes[scanStart] === 0x20) scanStart++;
  let nullCount = 0;
  for (let i = scanStart; i < Math.min(scanStart + 50, bytes.length - 1); i += 2) {
    if (bytes[i] !== 0 && bytes[i+1] === 0) nullCount++;
  }

  if (nullCount > 5) {
    try {
      const decoder = new TextDecoder("utf-16-le");
      const slice = buffer.slice(scanStart);
      const text = decoder.decode(slice);
      return text.replace(/^\uFEFF/, '');
    } catch(e) {
      const chars = [];
      for (let i = scanStart; i + 1 < bytes.length; i += 2) {
        const c = bytes[i] | (bytes[i+1] << 8);
        if (c !== 0 && c !== 0xFEFF) chars.push(String.fromCharCode(c));
      }
      return chars.join('');
    }
  }

  // -- UTF-8 / Latin-1 ----------------------------------------------------
  try {
    const decoder = new TextDecoder("utf-8");
    let start = 0;
    while (start < 10 && (bytes[start] === 0x20 || bytes[start] === 0xEF || bytes[start] === 0xBB || bytes[start] === 0xBF)) start++;
    return decoder.decode(buffer.slice(start));
  } catch(e) {
    let start = 0;
    while (start < 10 && bytes[start] === 0x20) start++;
    const chars = [];
    for (let i = start; i < bytes.length; i++) chars.push(String.fromCharCode(bytes[i]));
    return chars.join('').replace(/^[ÿþÿþï»¿]+/, '');
  }
}

// -- parseXLS: يقرأ ملف Excel بـ SheetJS ويدعم .xlsx/.xls/.tsv ------------
async function parseXLS(file) {
  // -- استراتيجية الإقراء: نجرب 3 طرق بالترتيب -------------------------

  const readAsText = (f, enc) => new Promise((res, rej) => {
    const r = new FileReader();
    r.onload  = e => res(e.target.result);
    r.onerror = () => rej(new Error('فشل قراءة الملف بـ ' + enc));
    r.readAsText(f, enc);
  });

  const readAsBuffer = (f) => new Promise((res, rej) => {
    const r = new FileReader();
    r.onload  = e => res(e.target.result);
    r.onerror = () => rej(new Error('فشل قراءة الملف'));
    r.readAsArrayBuffer(f);
  });

  // -- تحليل النص إلى صفوف ---------------------------------------------
  const parseText = (raw) => {
    // إزالة BOM وأي رموز غريبة
    const text = raw
      .replace(/^\uFEFF/, '')
      .replace(/^[\s\xFF\xFE]+/, '');

    const lines = text.split(/\r?\n/).filter(l => l.trim());
    if (lines.length < 2) return null;

    const headers = lines[0].split('\t').map(h =>
      h.replace(/\uFEFF/g,'').replace(/\r/g,'').replace(/"/g,'').trim()
    );

    // تحقق من وجود الأعمدة المطلوبة
    if (!headers.includes('Region') && !headers.includes('Paid Amount')) {
      console.warn('[parseXLS] Headers found:', headers.slice(0,8).join(', '));
      return null;
    }

    const rows = lines.slice(1)
      .filter(l => l.trim())
      .map(line => {
        const v = line.split('\t');
        const o = {};
        headers.forEach((h, i) => {
          o[h] = (v[i] || '').replace(/\r/g,'').replace(/"/g,'').trim();
        });
        return o;
      })
      .filter(r => r['Region']);

    console.log('[parseXLS] Parsed', rows.length, 'rows, headers:', headers.slice(0,6).join(', '));
    return rows;
  };

  // -- محاولة SheetJS (إذا كان محملاً) ---------------------------------
  const tryXLSX = async () => {
    try {
      const XLSX = window.XLSX;
      if (!XLSX) return null;
      const buf = await readAsBuffer(file);
      const wb = XLSX.read(new Uint8Array(buf), { type: 'array' });
      let wsName = wb.SheetNames[0];
      for (const name of wb.SheetNames) {
        const ws = wb.Sheets[name];
        const s  = XLSX.utils.sheet_to_json(ws, { header:1, range:0, defval:'' });
        const h  = (s[0]||[]).map(v => String(v||'').trim());
        if (h.includes('Region') || h.includes('Paid Amount')) { wsName = name; break; }
      }
      const rows = XLSX.utils.sheet_to_json(wb.Sheets[wsName], { raw:false, defval:'' });
      if (rows.length > 0) { console.log('[parseXLS] SheetJS OK:', rows.length); return rows; }
      return null;
    } catch(e) { console.warn('[parseXLS] SheetJS failed:', e.message); return null; }
  };

  // -- ترتيب المحاولات --------------------------------------------------
  let rows = null;

  // 1. SheetJS
  rows = await tryXLSX();

  // 2. UTF-16 LE (الأكثر شيوعاً لـ Excel export)
  if (!rows) {
    try {
      const t = await readAsText(file, 'UTF-16LE');
      rows = parseText(t);
      if (rows) console.log('[parseXLS] UTF-16LE OK');
    } catch(e) { console.warn('[parseXLS] UTF-16LE failed:', e.message); }
  }

  // 3. UTF-8
  if (!rows) {
    try {
      const t = await readAsText(file, 'UTF-8');
      rows = parseText(t);
      if (rows) console.log('[parseXLS] UTF-8 OK');
    } catch(e) { console.warn('[parseXLS] UTF-8 failed:', e.message); }
  }

  // 4. Windows-1252
  if (!rows) {
    try {
      const t = await readAsText(file, 'windows-1252');
      rows = parseText(t);
      if (rows) console.log('[parseXLS] windows-1252 OK');
    } catch(e) { console.warn('[parseXLS] windows-1252 failed:', e.message); }
  }

  // 5. ArrayBuffer + detectAndDecode (الاحتياطي الأخير)
  if (!rows) {
    try {
      const buf = await readAsBuffer(file);
      const text = detectAndDecode(buf);
      rows = parseText(text);
      if (rows) console.log('[parseXLS] detectAndDecode OK');
    } catch(e) { console.warn('[parseXLS] detectAndDecode failed:', e.message); }
  }

  if (!rows || rows.length === 0) {
    throw new Error(
      'تعذّر قراءة الملف. تأكد أن الملف بصيغة .xls أو .xlsx أو .tsv وأنه يحتوي أعمدة: Region, Paid Amount, Branch, Collector'
    );
  }

  // ======================================================================
  // تحليل البيانات بدقة
  // ======================================================================
  const n = v => {
    if (v == null || v === '') return 0;
    return parseFloat(String(v).replace(/,/g,'').replace(/[^0-9.-]/g,'')) || 0;
  };

  const REG_AR = {
    "Dhofar":                                        "ظفار",
    "Dhofar ":                                       "ظفار",
    "Musandam, Al Burimai and Al Dahirah":           "مسندم، البريمي والظاهرة",
    "MUSCAT AND AL DAKHILIYAH":                      "مسقط والداخلية",
    "North and South Al Shaurqiah and Al Wasatah":   "الشرقية الشمالية والجنوبية والوسطى",
    "South and North Al Batinah":                    "الباطنة الشمالية والجنوبية"
  };

  // -- بيانات المحافظ الحقيقية من ملف complaints ------------------------
  const PORT = {
    regions: {
      "Dhofar":                                      { portAmt: 1946.119,    portCnt: 25   },
      "Dhofar ":                                     { portAmt: 1946.119,    portCnt: 25   },
      "Musandam, Al Burimai and Al Dahirah":         { portAmt: 37449.515,   portCnt: 491  },
      "MUSCAT AND AL DAKHILIYAH":                    { portAmt: 68131.760,   portCnt: 1279 },
      "North and South Al Shaurqiah and Al Wasatah": { portAmt: 164461.982,  portCnt: 2463 },
      "South and North Al Batinah":                  { portAmt: 93541.029,   portCnt: 2219 }
    },
    dc: {
      "Matrix Debt Collection":        { portAmt: 2882018.894, portCnt: 23398 },
      "National Center":               { portAmt: 1014744.033, portCnt: 6741  },
      "Compass Risk Support Services": { portAmt: 386199.737,  portCnt: 3992  },
      "Ejada":                         { portAmt: 0,           portCnt: 1938  },
      "Tahseel United":                { portAmt: 0, principalAmt: 0, portCnt: 108   },
      "High Speed Company":            { portAmt: 0, principalAmt: 0, portCnt: 35    },
      "High Speed company":            { portAmt: 0, principalAmt: 0, portCnt: 35    },
      "Eemad":                         { portAmt: 0, principalAmt: 0, portCnt: 0     }
    },
    ho: {
      "Legal - DR. Sarhaan": { portAmt: 3229651.681, portCnt: 3691, closed:67, active:3624, principalAmt: 3301711.348 },
      "Documentation- Omantel": { portAmt: 471756.070,  portCnt: 1099, closed:8, active:1091 },
      "Legal -Oneic":{portAmt:64528.164,portCnt:101,principalAmt:64528.164,closed:101,active:0},"Refund - before legal":{portAmt:0,portCnt:0,closed:0,active:0},"Refund - after legal":{portAmt:0,portCnt:0,closed:0,active:0},
      "HO":                  { portAmt: 0,           portCnt: 340  },
      "Non-due accounts":    { portAmt: 0,           portCnt: 340  }
    }
  };

  const regMap = {}, dcMap = {}, hoMap = {};

  rows.forEach(row => {
    const region  = (row['Region']      || row['region']      || '').trim();
    const paid    = n(row['Paid Amount']|| row['paid_amount']  || row['Paid'] || 0);
    const adj     = n(row['Adjustment'] || row['adjustment']   || row['Adj']  || 0);
    const _osRaw  = row['O/S Amount'] != null && row['O/S Amount'] !== '' ? row['O/S Amount'] : (row['os_amount'] != null && row['os_amount'] !== '' ? row['os_amount'] : (row['Outstanding'] != null && row['Outstanding'] !== '' ? row['Outstanding'] : (row['O/S'] != null && row['O/S'] !== '' ? row['O/S'] : 0)));
    const osAmt   = parseFloat(String(_osRaw).replace(/,/g,'')) || 0;
    const rowPort  = osAmt; // O/S Amount
    const col     = (row['Collector']   || row['collector']    || '').trim();
    const branch  = (row['Branch']      || row['branch']       || '').trim();

    if (region === 'Debt Collection Company') {
      // تطبيع أسماء شركات التحصيل
      var dcNormMap = {'Murtafaat Basteen Fida LLC':'Eemad','Murtafaat Basteen':'Eemad','مرتفعات بستان':'Eemad','Eemad (Murtafaat Basteen Fida LLC)':'Eemad','Eemad (Murtafaat Basteen)':'Eemad'};
      const rawKey = branch || col || 'Unknown';
      const key = dcNormMap[rawKey] || rawKey;
      if (!dcMap[key]) dcMap[key] = { paid:0, adj:0, count:0, paidCount:0, adjCount:0, osAmt:0, principalAmt:0 };
      dcMap[key].paid  += paid; dcMap[key].adj += adj; dcMap[key].count++; dcMap[key].osAmt += rowPort; dcMap[key].principalAmt += n(row['Principal Amount']||0);
      if (paid>0) dcMap[key].paidCount++;
      if (adj >0) dcMap[key].adjCount++;

    } else if (region === 'Head Office' || region === 'Legal' || region === 'Legal ') {
      const colL = col.toLowerCase();
      let key = 'HO';
      if      (colL.includes('dr') || colL.includes('sarhaan') || colL.includes('sarhan')) key = 'Legal - DR. Sarhaan';
      else if (colL.includes('doc'))  { key = 'Documentation- Omantel'; }
      else if (colL.includes('non-due') || colL.includes('nondue')) key = 'HO';
      else if (col.trim().toUpperCase() === 'HO') key = 'HO';
      else if (colL.includes('refund') && colL.includes('before')) key = 'Refund - before legal';
      else if (colL.includes('refund') && colL.includes('after'))  key = 'Refund - after legal';
      else if (colL.includes('refund')) key = 'Refund - before legal';
      else if (colL.includes('communication') || colL.includes('omantel communication')) key = 'Omantel Communication';
      else if (colL.includes('initial loss') || colL === 'initial loss') key = 'Initial Loss';
      else if (colL.includes('saif')) key = 'Legal -Oneic';
      else if (col.trim() === '')     key = 'Legal -Oneic';
      else                            key = col.trim() || 'Legal -Oneic';
      if (!hoMap[key]) hoMap[key] = { paid:0, adj:0, count:0, closed:0, active:0, principalAmt:0, ctExpat:0, ctOman:0, ctEnterprise:0, vsExpired:0, vsNotExpired:0, vsNoData:0, ctExpat_os:0, ctOman_os:0, ctEnterprise_os:0, vsExpired_os:0, vsNotExpired_os:0, vsNoData_os:0 };
      hoMap[key].paid += paid; hoMap[key].adj += adj; hoMap[key].count++; hoMap[key].principalAmt += n(row['Principal Amount']||0);
      // Customer Type & Visa Status + O/S Amount
      var ct = (row['Customer Type']||'').trim().toLowerCase();
      var vs = (row['Visa Status']||'').trim().toLowerCase();
      var rowOs = n(row['O/S Amount']||0);
      if (ct.includes('expat')) { hoMap[key].ctExpat++; hoMap[key].ctExpat_os=Math.round((hoMap[key].ctExpat_os+rowOs)*1000)/1000; }
      else if (ct.includes('enterprise')||ct.includes('company')) { hoMap[key].ctEnterprise++; hoMap[key].ctEnterprise_os+=rowOs; }
      else if (ct.includes('oman')) { hoMap[key].ctOman++; hoMap[key].ctOman_os+=rowOs; }
      if (vs.includes('not expired')||vs.includes('valid')) { hoMap[key].vsNotExpired++; hoMap[key].vsNotExpired_os=Math.round((hoMap[key].vsNotExpired_os+rowOs)*1000)/1000; }
      else if (vs.includes('expired')) { hoMap[key].vsExpired++; hoMap[key].vsExpired_os=Math.round((hoMap[key].vsExpired_os+rowOs)*1000)/1000; }
      else if (vs) { hoMap[key].vsNoData++; hoMap[key].vsNoData_os=Math.round((hoMap[key].vsNoData_os+rowOs)*1000)/1000; }
      const _hoTracked = ['Legal -Oneic','Documentation- Omantel','Legal - DR. Sarhaan','HO','Refund - before legal','Refund - after legal','Omantel Communication','Initial Loss'];
      if (_hoTracked.includes(key)) { if (osAmt<=0) hoMap[key].closed++; else hoMap[key].active++; }

    } else if (REG_AR[region]) {
      if (!regMap[region]) regMap[region] = { paid:0, adj:0, count:0, paidCount:0, adjCount:0, cMap:{}, principalAmt:0 };
      regMap[region].paid  += paid; regMap[region].adj += adj; regMap[region].count++;
      regMap[region].principalAmt = (regMap[region].principalAmt||0) + n(row['Principal Amount']||0);
      if (paid>0) regMap[region].paidCount++;
      if (adj >0) regMap[region].adjCount++;
      if (col) {
        if (!regMap[region].cMap[col]) regMap[region].cMap[col] = { paid:0, adj:0, count:0, paidCount:0, adjCount:0, osAmt:0, principalAmt:0 };
        regMap[region].cMap[col].paid  += paid;
        regMap[region].cMap[col].adj   += adj;
        regMap[region].cMap[col].count++;
        regMap[region].cMap[col].osAmt += rowPort;
        regMap[region].cMap[col].principalAmt += n(row['Principal Amount']||0);
        if (paid>0) regMap[region].cMap[col].paidCount++;
        if (adj >0) regMap[region].cMap[col].adjCount++;
      }
    }
  });

  // -- بناء المناطق ------------------------------------------------------
  const REG_ORDER = [
    "Dhofar ","Dhofar",
    "Musandam, Al Burimai and Al Dahirah",
    "MUSCAT AND AL DAKHILIYAH",
    "North and South Al Shaurqiah and Al Wasatah",
    "South and North Al Batinah"
  ];
  const regions = REG_ORDER.filter(k => regMap[k]).map(k => ({
    id: k.toLowerCase().replace(/\s+/g,'_').replace(/[^a-z0-9_]/g,''),
    nameAr: REG_AR[k], nameEn: k.trim(),
    paid: regMap[k].paid, adj: regMap[k].adj,
    count: regMap[k].count||0,
    paidCount: regMap[k].paidCount||0,
    adjCount:  regMap[k].adjCount||0,
    portAmt: regMap[k].principalAmt||(PORT.regions[k]||{portAmt:0}).portAmt,
    principalAmt: regMap[k].principalAmt||0,
    portCnt: regMap[k].count || (PORT.regions[k]||{portCnt:0}).portCnt,
    collectors: Object.entries(regMap[k].cMap)
      .map(([nm,d]) => ({
        name:nm, paid:d.paid, adj:d.adj,
        count:d.count||0, paidCount:d.paidCount||0, adjCount:d.adjCount||0,
        portAmt:d.osAmt||0, portCnt:d.count||0, principalAmt:d.principalAmt||0
      }))
      .sort((a,b) => { var pa=a.principalAmt>0?a.principalAmt:(a.portAmt||0); var pb=b.principalAmt>0?b.principalAmt:(b.portAmt||0); var pctA=pa>0?((a.paid||0)+(a.adj||0))/pa:0; var pctB=pb>0?((b.paid||0)+(b.adj||0))/pb:0; return pctB-pctA; })
  }));

  // -- شركات التحصيل -----------------------------------------------------
  const DC_REQUIRED = ["Matrix Debt Collection","National Center","Compass Risk Support Services","Ejada","Tahseel United","High Speed Company","Eemad"];
  const dcList = Object.entries(dcMap).map(([nm,d]) => {
    const p = PORT.dc[nm.trim()] || {portAmt:0,portCnt:0};
    // portAmt: من الملف (osAmt) إذا متاح، وإلا من PORT.dc
    const computedPortAmt = d.principalAmt > 0 ? d.principalAmt : p.portAmt;
    return { name:nm.trim(), paid:d.paid, adj:d.adj,
      count:d.count||0, paidCount:d.paidCount||0, adjCount:d.adjCount||0,
      portAmt:computedPortAmt, portCnt:d.count||p.portCnt, osAmt:d.osAmt||0 };
  });
  DC_REQUIRED.forEach(nm => {
    if (!dcList.find(c=>c.name.toLowerCase()===nm.toLowerCase())) {
      const p = PORT.dc[nm]||{portAmt:0,portCnt:0};
      dcList.push({name:nm,paid:0,adj:0,count:0,paidCount:0,adjCount:0,portAmt:p.portAmt,portCnt:p.portCnt});
    }
  });
  const debtCompanies = dcList.sort((a,b)=>((b.paid||0)+(b.adj||0))-((a.paid||0)+(a.adj||0)));

  // -- المكتب الرئيسي ----------------------------------------------------
  const HO_KEYS = ["Legal - DR. Sarhaan","Documentation- Omantel","HO","Legal -Oneic","Initial Loss"];
  const HO_DISPLAY_MAP = {"HO":"Non-due accounts","Non-due accounts":"Non-due accounts","Documentation- Omantel":"Documentation- Omantel","Legal - DR. Sarhaan":"Legal - DR. Sarhaan","Legal -Oneic":"Legal -Oneic","Initial Loss":"Initial Loss"};
  const headOffice = HO_KEYS.map(nm => {
    const d = hoMap[nm]||{paid:0,adj:0,count:0,principalAmt:0,closed:0,active:0,ctExpat:0,ctOman:0,ctEnterprise:0,vsExpired:0,vsNotExpired:0,vsNoData:0};
    const p = PORT.ho[nm]||{portAmt:0,portCnt:0};
    // استخدم count من الملف إذا كان PORT.portCnt صفر (محصّل جديد)
    const finalPortCnt = (d.count>0 && d.count>(p.portCnt||0)) ? d.count : (p.portCnt||0);
    const finalPortAmt = Math.max(0, d.principalAmt||p.portAmt||0);
    return {name:HO_DISPLAY_MAP[nm]||nm, paid:d.paid, adj:d.adj, count:d.count||0,
      closed:d.closed||0, active:d.active||0,
      portAmt:finalPortAmt, portCnt:finalPortCnt, principalAmt:finalPortAmt,
      ctExpat:d.ctExpat||0, ctOman:d.ctOman||0, ctEnterprise:d.ctEnterprise||0,
      vsExpired:d.vsExpired||0, vsNotExpired:d.vsNotExpired||0, vsNoData:d.vsNoData||0,
      ctExpat_os:d.ctExpat_os||0, ctOman_os:d.ctOman_os||0, ctEnterprise_os:d.ctEnterprise_os||0,
      vsExpired_os:d.vsExpired_os||0, vsNotExpired_os:d.vsNotExpired_os||0, vsNoData_os:d.vsNoData_os||0};
  });
  // خزّن CT/VS في window للاستخدام في مسار الـ complaints
  try { window._pendingHOCTVS = {}; headOffice.forEach(function(h){ window._pendingHOCTVS[h.name] = { ctExpat:h.ctExpat||0, ctOman:h.ctOman||0, ctEnterprise:h.ctEnterprise||0, vsExpired:h.vsExpired||0, vsNotExpired:h.vsNotExpired||0, vsNoData:h.vsNoData||0, ctExpat_os:h.ctExpat_os||0, ctOman_os:h.ctOman_os||0, ctEnterprise_os:h.ctEnterprise_os||0, vsExpired_os:h.vsExpired_os||0, vsNotExpired_os:h.vsNotExpired_os||0, vsNoData_os:h.vsNoData_os||0 }; }); } catch(e) {}
  const HO_DN={"HO":"Non-due accounts","Non-due accounts":"Non-due accounts"};
  Object.keys(hoMap).forEach(k => {
    if (!HO_KEYS.includes(k))
      headOffice.push({name:HO_DN[k]||k,paid:hoMap[k].paid,adj:hoMap[k].adj,count:hoMap[k].count||0,
        portAmt:hoMap[k].principalAmt||0, portCnt:hoMap[k].count||0,
        closed:hoMap[k].closed||0, active:hoMap[k].active||0,
        ctExpat:hoMap[k].ctExpat||0, ctOman:hoMap[k].ctOman||0, ctEnterprise:hoMap[k].ctEnterprise||0,
        vsExpired:hoMap[k].vsExpired||0, vsNotExpired:hoMap[k].vsNotExpired||0, vsNoData:hoMap[k].vsNoData||0});
  });

  return {
    uploadDate: new Date().toISOString().split('T')[0],
    totalRecords: rows.length,
    regions, debtCompanies, headOffice,
    totalPortfolio: {
      amt: rows.reduce((s,r)=>s+n(r['Principal Amount']||0),0),
      cnt: rows.length,
      outstanding: rows.reduce((s,r)=>s+n(r['O/S Amount']||0),0)
    }
  };
}



const FIREBASE_URL = "https://oneic-dashboard-default-rtdb.firebaseio.com";

// ═══ ONE-TIME DATA FIX v8 ═════════════════════════════════
// يُصلح Firebase: يُحافظ على history/uploadCount + يُضيف شركات جديدة (Eemad)
(function() {
  if (typeof window === 'undefined') return;
  if (localStorage.getItem('oneic_data_fixed_v13')) return;
  var REQUIRED_DC = ['Matrix Debt Collection','National Center','Compass Risk Support Services','Ejada','Tahseel United','High Speed Company','Eemad'];
  var now = new Date().toISOString();
  fetch('https://oneic-dashboard-default-rtdb.firebaseio.com/main.json')
    .then(function(r){ return r.json(); })
    .then(function(existing) {
      var existDC = (existing && existing.debtCompanies)||[];
      var hasValidBase = existDC.some(function(c){ return c.name==='Matrix Debt Collection'||c.name==='National Center'; });
      var hasAllRequired = REQUIRED_DC.every(function(nm){ return existDC.some(function(c){ return c.name===nm; }); });
      var existHO = (existing && existing.headOffice)||[];

      if (hasValidBase && hasAllRequired && existing && existing.regions && existing.regions.length > 0) {
        // البيانات صحيحة — لكن دائماً حدّث CT/VS من SEED (قد تكون قيم جديدة)
        var mergedDC2 = existDC.slice();
        SEED.debtCompanies.forEach(function(seedCo) {
          var exists = mergedDC2.some(function(c){ return c.name===seedCo.name; });
          if (!exists) mergedDC2.push(seedCo);
        });
        // استخدم SEED للـ CT/VS دائماً كـ fallback محدّث
                var mergedHO2 = (existing.headOffice||[]).map(function(h) {
          var s = (SEED.headOffice||[]).find(function(x){ return x.name===h.name; });
          if (!s) return h;
          var hasOwn = h.ctExpat||h.vsExpired||h.vsNotExpired||h.vsNoData||h.ctOman||h.ctEnterprise;
          var hasOs  = h.ctExpat_os>0||h.vsExpired_os>0||h.vsNotExpired_os>0;
          // Firebase يحتوي بيانات من رفع ملف → احتفظ بها
          if (hasOwn && hasOs) return h;
          // Firebase يحتوي أعداد لكن بدون os → أضف os من SEED
          if (hasOwn) {
            return Object.assign({},h,{
              ctExpat_os: h.ctExpat_os||s.ctExpat_os||0,
              ctOman_os:  h.ctOman_os||s.ctOman_os||0,
              ctEnterprise_os:h.ctEnterprise_os||s.ctEnterprise_os||0,
              vsExpired_os:   h.vsExpired_os||s.vsExpired_os||0,
              vsNotExpired_os:h.vsNotExpired_os||s.vsNotExpired_os||0,
              vsNoData_os:    h.vsNoData_os||s.vsNoData_os||0
            });
          }
          // Firebase فارغ → خذ من SEED
          return Object.assign({},h,{
            ctExpat:s.ctExpat||0, ctOman:s.ctOman||0, ctEnterprise:s.ctEnterprise||0,
            vsExpired:s.vsExpired||0, vsNotExpired:s.vsNotExpired||0, vsNoData:s.vsNoData||0,
            ctExpat_os:s.ctExpat_os||0, ctOman_os:s.ctOman_os||0, ctEnterprise_os:s.ctEnterprise_os||0,
            vsExpired_os:s.vsExpired_os||0, vsNotExpired_os:s.vsNotExpired_os||0, vsNoData_os:s.vsNoData_os||0
          });
        });
        // أضف أي محصّل في SEED غير موجود في Firebase
        SEED.headOffice.forEach(function(s) {
          var ex = mergedHO2.find(function(h){ return h.name===s.name; });
          if (!ex) mergedHO2.push(s);
        });
        var fixData2 = Object.assign({}, existing, {
          debtCompanies: mergedDC2, headOffice: mergedHO2,
          lastUpdated: now, _updatedAt: now,
        });
        try { localStorage.setItem('oneic_dashboard_data', JSON.stringify(fixData2)); } catch(e) {}
        fetch('https://oneic-dashboard-default-rtdb.firebaseio.com/main.json', {
          method:'PUT', headers:{'Content-Type':'application/json'}, body:JSON.stringify(fixData2)
        }).then(function(){
          try { localStorage.setItem('oneic_data_fixed_v13','1'); } catch(e) {}
          console.log('[ONEIC] Fix v11: CT/VS synced from SEED');
        }).catch(function(){
          try { localStorage.setItem('oneic_data_fixed_v13','1'); } catch(e) {}
        });
        return;
      }
      // البيانات خاطئة — استخدم SEED كاملاً
      var fixData = Object.assign({}, SEED, {
        lastUpdated: now, _updatedAt: now,
        totalPortfolio: SEED.totalPortfolio,
        history: (existing && existing.history && existing.history.length > 0) ? existing.history : [],
        uploadCount: (existing && existing.uploadCount && existing.uploadCount > 1) ? existing.uploadCount : (SEED.uploadCount||1),
      });
      try { localStorage.setItem('oneic_dashboard_data', JSON.stringify(fixData)); } catch(e) {}
      fetch('https://oneic-dashboard-default-rtdb.firebaseio.com/main.json', {
        method: 'PUT', headers: {'Content-Type':'application/json'}, body: JSON.stringify(fixData)
      }).then(function() {
        try { localStorage.setItem('oneic_data_fixed_v13','1'); } catch(e) {}
        console.log('[ONEIC] Fix v11: SEED written to Firebase');
      }).catch(function(e) { console.warn('[ONEIC] Fix v11 failed:', e.message); });
    }).catch(function() {
      try { localStorage.setItem('oneic_dashboard_data', JSON.stringify(SEED)); } catch(e) {}
      try { localStorage.setItem('oneic_data_fixed_v13','1'); } catch(e) {}
    });
})();
