        setComplaintsAmts({dc:dcAmt,ho:hoAmt,gov:govAmt});
        setComplaintsPrincipal({dc:dcAmt,ho:hoAmt,gov:govAmt});
        setComplaintsPaidState({dc:dcPaid,ho:hoPaid,gov:govPaid});
